  let vacations = [];
  for (let i = 1; i < tmp.length; i++ ){
    let vacation = tmp[i].split(" ").map(element => parseInt(element, 10));
    vacations.push(vacation);
  }
  let dp = [0, 0, 0];
  for (let day = 0; day < vacations.length; day++) {
    let vacation = vacations[day];
    let new_dp = [0, 0, 0];
